"""Gemini chat router (FastAPI) mirroring old Node /api/gemini/chat."""

import os
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel
from langchain_core.prompts import ChatPromptTemplate
from langchain_groq import ChatGroq 

#importe da função para os dados 
from services.analytics_service import get_analytics_sumary_text

#configuraçao do roteador da api.
router = APIRouter()

#modelo de entrada/ usado pelo front. 
class ChatRequest(BaseModel):
    message : str

 # iniciando o agente
chat = ChatGroq(
    model = "llama-3.3-70b-versatile", 
    temperature= 0.7, 
    max_tokens= 2048, api_key = os.getenv("GEMINI_API_KEY")
)


prompt = ChatPromptTemplate.from_messages([("system", """Você é o Diretor Comercial e Estrategista de Vendas do Citi, sua função é analisar os KPIs do pipeline de vendas e fornecer INSIGHTS e DICAS ACIONÁVEIS.
REGRAS DE COMPORTAMENTO:
    1. NÃO repita os números que o usuário já está vendo na tela, a menos que seja para provar um ponto.
    2. Identifique gargalos (ex: muitos leads parados em uma fase inicial).
    3. Sugira estratégias práticas de vendas para bater a meta ou melhorar a conversão.
    4. Seja consultivo, analítico, direto e encorajador.
    
    Abaixo estão os dados reais e exatos calculados pelo sistema neste exato momento:
    {contexto_analytics}"""


), ("human", "{input}")])

#para conectar o programa ao modelo. 
chain = prompt | chat 

#Rota Post de espelhamento do antigo Node /api/gemini/chat. 
@router.post("/chat")
async def process_chat(request: ChatRequest):
    try:
        #busca os dados reais e atualiza o banco 
        dados_atualizados = get_analytics_sumary_text() 

        #chamando a resposta 
        resposta_ia = chain.invoke({
            "contexto_analytics": dados_atualizados, 
            "input": request.message
        })
        
        # retorno no formato que o front espera (texto puro extraído do objeto)
        return {"response": resposta_ia.content}
    
    except Exception as e: 
        print(f"❌ Erro no Agente IA: {str(e)}")
        # Tratamento de erro elegante (A nossa task de resiliência!)
        raise HTTPException(
            status_code=500, 
            detail="Nossa inteligência artificial está indisponível no momento. Tente novamente em instantes."
        )